.segmented-control {
  --segmented-label: #6b675e;
  --segmented-track: #e9e6df;
  --segmented-track-border: rgba(31, 29, 25, 0.08);
  --segmented-text: #4a4740;
  --segmented-text-hover: #1f1d19;
  --segmented-selected-bg: #ffffff;
  --segmented-selected-text: #1f1d19;
  --segmented-selected-shadow: 0 1px 2px rgba(31, 29, 25, 0.12),
    0 1px 1px rgba(31, 29, 25, 0.06);
  --segmented-focus: #3b6fd6;

  display: inline-flex;
  flex-direction: column;
  gap: 0.4rem;
  font-family: inherit;
}

:root[data-theme="night"] .segmented-control,
[data-theme="night"] .segmented-control {
  --segmented-label: #7d8592;
  --segmented-track: #1c1f26;
  --segmented-track-border: rgba(238, 241, 246, 0.06);
  --segmented-text: #9aa1ad;
  --segmented-text-hover: #eef1f6;
  --segmented-selected-bg: #2b303b;
  --segmented-selected-text: #eef1f6;
  --segmented-selected-shadow: 0 1px 2px rgba(0, 0, 0, 0.4);
  --segmented-focus: #7aa7ff;
}

.segmented-control__label {
  font-size: 0.8125rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  color: var(--segmented-label);
}

.segmented-control__track {
  display: inline-flex;
  align-items: stretch;
  gap: 2px;
  padding: 3px;
  border-radius: 999px;
  background: var(--segmented-track);
  box-shadow: inset 0 0 0 1px var(--segmented-track-border);
}

.segmented-control__segment {
  appearance: none;
  border: 0;
  margin: 0;
  padding: 0.45rem 0.9rem;
  border-radius: 999px;
  background: transparent;
  color: var(--segmented-text);
  font: inherit;
  font-size: 0.875rem;
  font-weight: 500;
  line-height: 1.2;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background-color 160ms ease,
    color 160ms ease,
    box-shadow 160ms ease;
}

.segmented-control__segment:hover {
  color: var(--segmented-text-hover);
}

.segmented-control__segment[aria-checked="true"] {
  background: var(--segmented-selected-bg);
  color: var(--segmented-selected-text);
  box-shadow: var(--segmented-selected-shadow);
}

.segmented-control__segment:focus {
  outline: none;
}

.segmented-control__segment:focus-visible {
  outline: 2px solid var(--segmented-focus);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  .segmented-control__segment {
    transition: none;
  }
}
